import React, {useState, useCallback} from 'react';
import ReactTooltip from 'react-tooltip';

import {InfoIcon} from '@crucible-risk/icon';

interface TooltipProps {
  info: string;
  field: string;
}

export const Tooltip: React.FC<TooltipProps> = ({info, field}) => {
  const [showTooltip, setShowTooltip] = useState(false);
  const uniqueId = `tooltip-${field}`;

  // Memoized event handlers
  const handleFocus = useCallback(() => {
    setShowTooltip(true);
  }, []);

  const handleBlur = useCallback(() => {
    setShowTooltip(false);
  }, []);

  return (
    <>
      <button
        type="button"
        data-tip
        data-for={uniqueId}
        onFocus={handleFocus}
        onBlur={handleBlur}
      >
        <InfoIcon size={12} />
      </button>
      {showTooltip && (
        <ReactTooltip id={uniqueId} place="top" type="info" effect="float">
          {info}
        </ReactTooltip>
      )}
    </>
  );
};
