import * as React from 'react';
import {useFela} from 'react-fela';
import {Coverage} from '@crucible-risk/sku-api-schema';
import {Button} from '@crucible-risk/button';
import {Typography as T} from '@crucible-risk/typography';
import {formatCurrency} from '../../utils/intl';

import {
  COLUMN,
  CONTENT,
  LABEL,
  ROW,
  HEADER_ROW,
  VALUE,
  CHANGE_LINK,
} from './styles';

interface SelectedPlanInfoProps {
  content: {
    name: string;
    limit: string;
    deductible: string;
    premium: string;
  };
  name: string;
  limit: number;
  retention: number;
  premium: number;
  onChange: () => void;
  ftfCoverage?: Coverage;
}

export const SelectedPlanInfo = ({
  content,
  name,
  limit,
  retention,
  premium,
  onChange,
  ftfCoverage,
}: SelectedPlanInfoProps) => {
  const {css} = useFela();

  return (
    <div className={`bg-panel ${css(CONTENT)}`}>
      <div className={css(COLUMN)}>
        <div className={css(CHANGE_LINK)}>
          <Button size="xSmall" minimal onClick={onChange} sharpCorners>
            Change
          </Button>
        </div>

        <div className={css(HEADER_ROW)}>
          <div className={css(LABEL)}>
            <T
              className="body3 fg-body"
              variant="bodyRegular"
              weight="semibold"
            >
              {content.name}
            </T>
          </div>
          <div className={css(VALUE)}>
            <T
              className="body3 fg-body"
              variant="bodyRegular"
              weight="semibold"
            >
              {name}
            </T>
          </div>
        </div>

        <div className={css(ROW)}>
          <div className={css(LABEL)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {content.limit}
            </T>
          </div>
          <div className={css(VALUE)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {formatCurrency(limit / 100, {
                fractionDigits: 2,
                currency: 'USD',
              })}
            </T>
          </div>
        </div>
        <div className={css(ROW)}>
          <div className={css(LABEL)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {content.deductible}
            </T>
          </div>
          <div className={css(VALUE)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {formatCurrency(retention / 100, {
                fractionDigits: 2,
                currency: 'USD',
              })}
            </T>
          </div>
        </div>

        {ftfCoverage && ftfCoverage.sublimit && (
          <div className={css(ROW)}>
            <div className={css(LABEL)}>
              <T className="body3 fg-body" variant="bodyRegular">
                FTF Limit
              </T>
            </div>
            <div className={css(VALUE)}>
              <T className="body3 fg-body" variant="bodyRegular">
                {formatCurrency(ftfCoverage.sublimit.amount / 100, {
                  fractionDigits: 2,
                  currency: 'USD',
                })}
              </T>
            </div>
          </div>
        )}
        {ftfCoverage && ftfCoverage.subretention && (
          <div className={css(ROW)}>
            <div className={css(LABEL)}>
              <T className="body3 fg-body" variant="bodyRegular">
                FTF Deductible
              </T>
            </div>
            <div className={css(VALUE)}>
              <T className="body3 fg-body" variant="bodyRegular">
                {formatCurrency(ftfCoverage.subretention.amount / 100, {
                  fractionDigits: 2,
                  currency: 'USD',
                })}
              </T>
            </div>
          </div>
        )}

        <div className={css(ROW)}>
          <div className={css(LABEL)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {content.premium}
            </T>
          </div>
          <div className={css(VALUE)}>
            <T className="body3 fg-body" variant="bodyRegular">
              {formatCurrency(premium / 100, {
                fractionDigits: 2,
                currency: 'USD',
              })}
            </T>
          </div>
        </div>
      </div>
    </div>
  );
};

SelectedPlanInfo.displayName = 'SelectedPlanInfo';
