import React from 'react';
import {useFela} from 'react-fela';

import {CheckIcon} from '@crucible-risk/icon';
import {Typography} from '@crucible-risk/typography';

import {CHECKBOX_CONTAINER, CHECK, INPUT} from './styles';

interface Props
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange'> {
  checked: boolean;
  onChange: (value: boolean) => void;
}

export const Checkbox: React.FC<Props> = ({
  checked,
  onChange,
  name,
  id,
  ...props
}) => {
  const {css} = useFela();

  return (
    <div className={css(CHECKBOX_CONTAINER)}>
      {checked && (
        <div className={css(CHECK)}>
          <Typography color="coolGray400">
            <CheckIcon />
          </Typography>
        </div>
      )}

      <input
        type="checkbox"
        className={css(INPUT)}
        checked={checked}
        onChange={() => {
          onChange(!checked);
        }}
        name={name}
        id={id}
        {...props}
      />
    </div>
  );
};

Checkbox.displayName = 'Checkbox';
