import {Array, String, Unknown} from 'runtypes';

import {ApiClientBase} from '@crucible-risk/api-client-base';

import {
  InsurancePolicy,
  InsurancePolicySchema,
  InsurancePolicyResponseSchema,
  ConfigurationSchema,
  IndustrySchema,
  AttestationsSchema,
  InvoiceSchema,
  ApplicationQuestionsSchema,
  DistributionProgramsRequest,
} from '@crucible-risk/sku-api-schema';

export function withSku<TBase extends new (...args: any[]) => ApiClientBase>(
  Base: TBase,
) {
  return class WithSku extends Base {
    /**
     * Create an insurance policy. JWT in response header used for further
     * insurance_policy requests.
     *
     * @param data
     */
    createInsurancePolicy(data: Partial<InsurancePolicy>) {
      const url = '/customer-api/insurance_policy';

      return this.request(
        {
          method: 'POST',
          url,
          data,
        },
        InsurancePolicySchema,
        Unknown,
      );
    }

    /**
     * Get insurance policy based on Authorization JWT
     */
    getInsurancePolicy() {
      const url = '/customer-api/insurance_policy';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        InsurancePolicySchema,
        Unknown,
      );
    }

    /**
     *  Sets coverages based on configuration_id
     *
     * @param configuration_id Number
     */
    setConfiguration(configuration_id: number) {
      const url = '/customer-api/insurance_policy';

      return this.request(
        {
          method: 'PATCH',
          url,
          data: {
            configuration_id,
          },
        },
        InsurancePolicySchema,
        Unknown,
      );
    }

    /**
     * Create a quotation from a policy. Policy used is from Authorization JWT
     */
    createQuotation() {
      const url = '/customer-api/insurance_policy/quotation';

      return this.request(
        {
          method: 'POST',
          url,
          data: {}, // Necessary due to post request, otherwise webserver throws a fit (415)
        },
        InsurancePolicyResponseSchema,
        Unknown,
      );
    }

    /**
     * Get attestation statements for a policy based on Authorization JWT
     */
    getInsurancePolicyAttestation() {
      const url = '/customer-api/insurance_policy/attestation';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        AttestationsSchema,
        Unknown,
      );
    }

    payInsurancePolicy(data: {
      amount: {
        amount: number;
        code: string;
      };
      payment_processor_token: string;
      attestation_terms: boolean;
      attestation_legal: boolean;
      signature: string;
    }) {
      const url = '/customer-api/insurance_policy/invoice';

      return this.request(
        {
          method: 'PUT',
          url,
          data,
        },
        InvoiceSchema,
        Unknown,
      );
    }

    getInvoice() {
      const url = '/customer-api/insurance_policy/invoice';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        InvoiceSchema,
        Unknown,
      );
    }

    /**
     * Get all configurations available to organization
     */
    getConfigurations() {
      const url = '/customer-api/configurations';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        Array(ConfigurationSchema),
        Unknown,
      );
    }

    /**
     * Get entire list of industries available
     */
    listIndustries(industries?: number[]) {
      let url = '/customer-api/industries';

      if (industries) {
        url += `?id=${industries.join(',')}`;
      }

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        Array(IndustrySchema),
        Unknown,
      );
    }

    getApplicationQuestions() {
      const url = '/customer-api/insurance_policy/application_questions';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        ApplicationQuestionsSchema,
        Unknown,
      );
    }

    answerApplicationQuestions(data: {
      application_questions: {
        id: string;
        answer_text: string;
      }[];
    }) {
      const url = '/customer-api/insurance_policy/application_questions';

      return this.request(
        {
          method: 'PATCH',
          url,
          data,
        },
        ApplicationQuestionsSchema,
        Unknown,
      );
    }

    /**
     * Get available configurations for the policy based on
     * Authorization JWT
     */
    getInsurancePolicyConfigurations() {
      const url = '/customer-api/insurance_policy/configurations';

      return this.request(
        {
          method: 'GET',
          url,

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        Array(ConfigurationSchema),
        Unknown,
      );
    }

    downloadInsurancePolicyDocument(documentUuid: string) {
      const url = `/customer-api/documents/${documentUuid}`;

      return this.request(
        {
          method: 'GET',
          url,
          responseType: 'blob',

          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        Unknown,
        Unknown,
      );
    }

    getAffinityReferrer(partner: string, program: string) {
      // Ex. /affinity_referrer/intuit/cyberinsurance
      const url = `/affinity_referrer/${partner}/${program}`;

      return this.request(
        {
          method: 'GET',
          url,
          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        String,
        Unknown,
      );
    }

    getPartnerProgram(uuid: string) {
      // Ex. /partnership-program/cc32058a-7a30-45cc-ab5d-6e4af62f9371
      const url = `/partnership-program/${uuid}`;

      return this.request(
        {
          method: 'GET',
          url,
          /**
           * Adding an empty data value so that Axios will not strip the Content-Type header.
           * Remove once webserver removes this restraint
           */
          data: {},
        },
        String,
        Unknown,
      );
    }

    listAvailablePrograms(data: DistributionProgramsRequest) {
      const url = '/list-available-programs';

      return this.request(
        {
          method: 'POST',
          url,
          data,
        },
        Unknown,
        Unknown,
      );
    }
  };
}
