import {History} from 'history';
import {saveAs} from 'file-saver';
import {
  InsurancePolicy,
  InsurancePolicyDocument,
} from '@crucible-risk/sku-api-schema';

import {CreateActions, Reducer} from '../../lib/state';
import {createClient} from '../../lib/api';
import {getSession} from '../../lib/session';

interface SuccessManagerStateManagerProps {
  history: History;
  insurancePolicy: InsurancePolicy;
  sessionId: string;
}

interface SuccessState {
  downloading: {
    policy: boolean;
    riskAssessment: boolean;
  };
}

interface SuccessActions {
  downloadPolicy: () => void;
  downloadRiskAssessment: () => void;
}

type SuccessActionTypes = {
  type: 'DOWNLOADING_POLICY' | 'DOWNLOADING_RISKASSESSMENT';
  value: boolean;
};

export const createSuccessStateManager = ({
  insurancePolicy,
  sessionId,
}: SuccessManagerStateManagerProps) => {
  const initialState: SuccessState = {
    downloading: {
      policy: false,
      riskAssessment: false,
    },
  };

  const reducer: Reducer<SuccessState, SuccessActionTypes> = (
    state,
    action,
  ) => {
    switch (action.type) {
      case 'DOWNLOADING_POLICY':
        return {
          ...state,
          downloading: {...state.downloading, policy: action.value},
        };
      case 'DOWNLOADING_RISKASSESSMENT':
        return {
          ...state,
          downloading: {...state.downloading, riskAssessment: action.value},
        };
    }
    return state;
  };

  const createActions: CreateActions<
    SuccessState,
    SuccessActions,
    SuccessActionTypes
  > = (dispatch) => {
    const download = (
      policyDocument: InsurancePolicyDocument,
      type: 'DOWNLOADING_POLICY' | 'DOWNLOADING_RISKASSESSMENT',
    ) => {
      dispatch({type, value: true});

      const documentUuid = policyDocument.link.split('/').pop() ?? '';

      const client = createClient(getSession(sessionId));
      client
        .downloadInsurancePolicyDocument(documentUuid)
        .then((response) => {
          if (response.ok) {
            return response.data as any;
          }

          throw new Error('document-error');
        })
        .then((content) => {
          const blob = new Blob([content], {
            type: 'application/pdf',
          });

          saveAs(blob, `${insurancePolicy.name} ${policyDocument.label}.pdf`);
          dispatch({type, value: false});
        })
        .catch(() => {
          dispatch({type, value: false});
        });
    };

    const downloadPolicy = () => {
      const policyDocument = insurancePolicy.documents?.find(
        (document) => document.type === 'POLICY_BUNDLE',
      );

      if (policyDocument) {
        download(policyDocument, 'DOWNLOADING_POLICY');
      }
    };

    const downloadRiskAssessment = () => {
      const riskAssessmentDocument = insurancePolicy.documents?.find(
        (document) => document.type === 'CYBER_RISK_ASSESSMENT',
      );

      if (riskAssessmentDocument) {
        download(riskAssessmentDocument, 'DOWNLOADING_RISKASSESSMENT');
      }
    };

    return {
      downloadPolicy,
      downloadRiskAssessment,
    };
  };

  return {
    initialState,
    reducer,
    createActions,
  };
};
