import {StyleFunction} from 'react-fela';
import {tint} from 'polished';
import {
  formatTypeVariant,
  interactiveBorderRadius,
  fontWeights,
  colors,
} from '@crucible-risk/theme';

import {sizes, intents} from './button.config';

export const buttonStyle: StyleFunction<
  {},
  {
    fill: boolean;
    size: keyof typeof sizes;
    square: boolean;
    sharpCorners: boolean;
  }
> = ({fill, size = 'regular', square, sharpCorners}) => ({
  flex: fill ? '1 1 auto' : '0 0 auto',
  display: fill ? 'flex' : 'inline-flex',

  width: square ? sizes[size]?.height : fill ? '100%' : undefined,
  height: sizes[size]?.height,

  minWidth: 0,

  paddingLeft: !square ? sizes[size].padding + 4 : undefined,
  paddingRight: !square ? sizes[size].padding + 4 : undefined,

  position: 'relative',
  alignItems: 'center',
  justifyContent: 'center',
  cursor: 'pointer',
  borderRadius: sharpCorners ? 0 : 6,
  whiteSpace: 'nowrap',

  overflow: 'hidden',

  transition: 'background-color 100ms, color 100ms',

  ':disabled, :not(button):not(:link) ': {
    opacity: 0.5,
    cursor: 'default',
    pointerEvents: 'none',
  },
});

export const colorStyle: StyleFunction<
  {},
  {
    intent: keyof typeof intents;
    minimal: boolean;
    outline: boolean;
    background: boolean;
    sharpCorners: boolean;
  }
> = ({intent = 'primary', minimal, outline, background, sharpCorners}) => {
  if (minimal) {
    return {
      color: intents[intent]?.textColor,

      ':not(a):not(:disabled):hover, :link:hover': {
        backgroundColor: tint(0.9, intents[intent]?.color),
      },

      ':not(a):not(:disabled):active, :link:active': {
        color: tint(0.2, intents[intent]?.textColor),
        backgroundColor: tint(0.9, tint(0.2, intents[intent]?.color)),
      },
    };
  }

  if (outline) {
    return {
      color: intents[intent]?.textColor,
      backgroundColor: background
        ? tint(0.9, intents[intent]?.color)
        : undefined,

      '::before': {
        content: '""',
        display: 'block',
        position: 'absolute',
        top: 0,
        right: 0,
        bottom: 0,
        left: 0,

        pointerEvents: 'none',

        borderWidth: 2,
        borderRadius: sharpCorners ? 0 : interactiveBorderRadius,
        borderStyle: 'solid',
        borderColor: intents[intent]?.color,
      },

      ':not(a):not(:disabled):active, :link:active': {
        color: tint(0.2, intents[intent]?.textColor),

        '::before': {
          borderColor: tint(0.2, intents[intent]?.color),
        },
      },
    };
  }

  return {
    color: colors.white,
    backgroundColor: intents[intent]?.color,

    ':active:not(:disabled):not([aria-disabled=true])': {
      backgroundColor: tint(0.2, intents[intent]?.color),
    },
  };
};
export const spinnerStyle: StyleFunction<{}, {}> = () => ({
  position: 'absolute',
  display: 'flex',
  transformOrigin: '50%',
  pointerEvents: 'none',
  top: 0,
  right: 0,
  bottom: 0,
  left: 0,
  alignItems: 'center',
  justifyContent: 'center',
});

export const labelStyle: StyleFunction<
  {},
  {size: keyof typeof sizes; tight: boolean; square: boolean}
> = ({size = 'regular', tight, square}) => ({
  ...formatTypeVariant(sizes[size]?.typeVariant),
  lineHeight: sizes[size]?.height + 'px',
  fontWeight: fontWeights.semibold,

  position: 'relative',
  flex: '1 1 auto',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  minWidth: 0,

  transformOrigin: '50%',
  pointerEvents: 'none',

  paddingLeft:
    tight || square ? 0 : sizes[size]?.labelPadding - sizes[size]?.padding,
  paddingRight:
    tight || square ? 0 : sizes[size]?.labelPadding - sizes[size]?.padding,
});

export const statusStyle: StyleFunction<{}, {}> = () => ({
  position: 'absolute',
  top: 0,
  left: 0,
  right: 0,
  overflow: 'hidden',
  clip: 'rect(1px, 1px, 1px, 1px)',
});

export const appendStyle: StyleFunction<
  {},
  {loading: boolean; size: keyof typeof sizes}
> = ({loading}) => ({
  flex: '0 0 auto',
  display: 'flex',
  opacity: loading ? 0 : undefined,
  position: 'relative',

  transition: 'opacity 0.25s linear',
});

export const appendStartStyle: StyleFunction<
  {},
  {
    size: keyof typeof sizes;
  }
> = ({size = 'regular'}) => {
  return {
    paddingLeft: sizes[size].padding,
    paddingRight: sizes[size].padding,
    marginLeft: -sizes[size].padding - 4,

    pointerEvents: 'none',
  };
};

export const appendEndStyle: StyleFunction<
  {},
  {
    size: keyof typeof sizes;
  }
> = ({size = 'regular'}) => {
  return {
    paddingRight: sizes[size].padding,
    paddingLeft: sizes[size].padding,
    marginRight: -sizes[size].padding - 4,

    pointerEvents: 'none',
  };
};

export const linkButtonStyle: StyleFunction<
  {},
  {
    size: keyof typeof sizes;
    intent: keyof typeof intents;
  }
> = ({size = 'regular', intent = 'primary'}) => ({
  cursor: 'pointer',
  fontWeight: fontWeights.semibold,
  color: intents[intent]?.textColor,
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
});
