/**
 * For whatever reason we store the manual count of records in the same
 * field that we store the output from the data options select.
 * In admin-tools we have used isNaN to determine how to display
 * this information so I'm doing that here too.
 */

export function isNumber(value: any) {
  return !Number.isNaN(parseFloat(value)) && Number.isFinite(parseFloat(value));
}
