import {unregisterGlobalErrorHandler} from './setupErrorHandler';
import 'what-input';

import React from 'react';
import ReactDOM from 'react-dom';
import {RendererProvider} from 'react-fela';
import {BrowserRouter} from 'react-router-dom';

import {createRenderer} from '@crucible-risk/fela-renderer';

import {AppRoot} from './components/root/AppRoot';
import {LoadingProvider} from '/component/partial/LoadingProvider';
import {AffinityMonitoring} from './component/util/Monitoring';
import {ErrorBoundary} from './component/util/ErrorBoundary';
import {LaunchDarkly} from '/component/util/LaunchDarklyProvider';
import {launchDarklyClientId} from './config';

const renderer = createRenderer({
  devMode: __DEV__,
});

ReactDOM.render(
  <BrowserRouter>
    <AffinityMonitoring>
      <RendererProvider renderer={renderer}>
        <LaunchDarkly clientId={launchDarklyClientId}>
          <LoadingProvider>
            <ErrorBoundary>
              <AppRoot />
            </ErrorBoundary>
          </LoadingProvider>
        </LaunchDarkly>
      </RendererProvider>
    </AffinityMonitoring>
  </BrowserRouter>,
  document.getElementById('root'),
);

window._clearLoading();
unregisterGlobalErrorHandler();
