import axiosStatic, {
  AxiosRequestConfig,
  AxiosResponse,
  AxiosInstance,
} from 'axios';
import {Runtype, ValidationError} from 'runtypes';

export interface ResponseValidationError extends ValidationError {
  response: AxiosResponse<unknown>;
}

export interface GetAccessToken {
  (): Promise<string | undefined> | string | undefined | void;
}
export interface OnValidationError {
  (error: ResponseValidationError): void;
}

export interface Options {
  baseUrl?: string;
  getAccessToken?: GetAccessToken;
  onValidationError?: OnValidationError;
  axios?: AxiosInstance;
  shouldValidateResponseSchema?: boolean;
}

function getAccessToken() {}

function onValidationError(error: ResponseValidationError) {
  throw error;
}

export class Config {
  constructor(private _options: Options) {}

  get baseUrl(): string {
    return this._options.baseUrl ?? '';
  }

  get getAccessToken(): GetAccessToken {
    return this._options.getAccessToken ?? getAccessToken;
  }

  get onValidationError(): OnValidationError {
    return this._options.onValidationError ?? onValidationError;
  }

  get shouldValidateResponseSchema(): boolean {
    return this._options.shouldValidateResponseSchema ?? true;
  }

  get axios() {
    return this._options.axios ?? axiosStatic;
  }
}

export type ApiResponse<TReady, TFailed = unknown> =
  | {ok: true; data: TReady; status: number; headers: Record<string, string>}
  | {ok: false; data: TFailed; status: number; headers: Record<string, string>};

export interface Schema<T> {
  assert(x: any): asserts x is T;
}

export interface ApiClient {
  getAccessToken: GetAccessToken;
  request<TReady, TFailed>(
    config: AxiosRequestConfig,
    successSchema: Schema<TReady>,
    failureSchema: Schema<TFailed>,
  ): Promise<ApiResponse<TReady, TFailed>>;
}

export interface ApiClientConstructor {
  new (...args: any[]): ApiClient;
}

export interface ApiClientMixin {
  (base: ApiClientConstructor): ApiClientConstructor;
}

export class ApiClientBase implements ApiClient {
  config: Config;

  constructor(options: Options = {}) {
    this.config = new Config(options);
  }

  getAccessToken() {
    return this.config.getAccessToken();
  }

  request<TReady, TFailed>(
    config: AxiosRequestConfig,
    successSchema: Runtype<TReady>,
    failureSchema: Runtype<TFailed>,
  ): Promise<ApiResponse<TReady, TFailed>> {
    return Promise.resolve(this.config.getAccessToken())
      .then((accessToken) => {
        const headers: Record<string, string> = {
          'Content-Type': 'application/json; charset=UTF-8',
          Accept: 'application/json; charset=UTF-8',
          ...(config?.headers as Record<string, string>),
        };

        if (accessToken) {
          headers.Authorization = 'Bearer ' + accessToken;
        }

        return this.config.axios.request({
          ...config,
          validateStatus() {
            return true;
          },
          url: this.config.baseUrl + (config.url ?? ''),
          headers,
        });
      })
      .then((response) => {
        const handleValidationError = (error: unknown) => {
          if (error instanceof ValidationError) {
            const responseError = error as ResponseValidationError;
            responseError.response = response;
            this.config.onValidationError(responseError);
          } else {
            throw error;
          }
        };

        if (response.status >= 200 && response.status < 300) {
          if (this.config.shouldValidateResponseSchema) {
            try {
              successSchema.assert(response.data);
            } catch (error) {
              handleValidationError(error);
            }
          }

          return {
            ok: true,
            data: response.data as TReady,
            status: response.status,
            headers: transformHeaders(response.headers),
          };
        }

        if (this.config.shouldValidateResponseSchema) {
          try {
            failureSchema.assert(response.data);
          } catch (error) {
            handleValidationError(error);
          }
        }

        return {
          ok: false,
          data: response.data as TFailed,
          status: response.status,
          headers: transformHeaders(response.headers),
        };
      });
  }
}

function transformHeaders(
  headers: AxiosResponse['headers'],
): Record<string, string> {
  const transformedHeaders: Record<string, string> = {};
  for (const key in headers) {
    if (Object.prototype.hasOwnProperty.call(headers, key)) {
      transformedHeaders[key] = headers[key] as string;
    }
  }
  return transformedHeaders;
}

interface Method<TArgs extends any[], TReady, TFailed> {
  (...args: TArgs): Promise<ApiResponse<TReady, TFailed>>;
}

export type MethodData<TMethod> = TMethod extends Method<any, infer TReady, any>
  ? TReady
  : never;

export type MethodError<TMethod> = TMethod extends Method<
  any,
  any,
  infer TFailed
>
  ? TFailed
  : never;
