import * as React from 'react';
import {FormData} from '../../components/pages/Checkout';

import {
  useForm,
  FormChangeHandler,
  FormBlurHandler,
  FormFlags,
  FormFieldValue,
} from '../useForm';

const ZIP_REGEX = /^[0-9]{5}(?:-[0-9]{4})?$/;

export interface CheckoutFormValues {
  name: string;
  address_country: string;
  address_zip: string;
  attestation_legal: boolean;
  attestation_terms: boolean;
  partner_attestation: boolean;
  signature: string;
  auto_renewal: boolean;
  email: string;
}

export type CheckoutFormFieldValue = FormFieldValue<CheckoutFormValues>;

export type CheckoutFormFlags = FormFlags<CheckoutFormValues>;

export type CheckoutFormChangeHandler = FormChangeHandler<CheckoutFormValues>;

export type CheckoutFormBlurHandler = FormBlurHandler<CheckoutFormValues>;

const mapCheckoutForm = (values: CheckoutFormValues): Partial<FormData> => {
  return {
    name: values.name,
    address_country: values.address_country,
    address_zip: values.address_zip,
    attestation_legal: values.attestation_legal,
    attestation_terms: values.attestation_terms,
    partner_attestation: values.partner_attestation,
    signature: values.signature,
    auto_renewal: values.auto_renewal,

    email: values.email,
  };
};

const validateCheckoutFormField = (
  field: keyof CheckoutFormValues,
  value: CheckoutFormValues[keyof CheckoutFormValues],
  values: CheckoutFormValues,
) => {
  let error;

  if (field === 'name' && value === '') {
    error = 'Name is required';
  }

  if (field === 'address_country' && value === '') {
    error = 'Country is required';
  }

  if (field === 'address_zip' && typeof value === 'string') {
    if (value === '') {
      error = 'Zipcode is required';
    }

    if (!ZIP_REGEX.test(value)) {
      error = 'Zipcode is invalid';
    }
  }

  if (field === 'signature' && value === '') {
    error = 'Signature is required';
  }

  if (field === 'attestation_legal' && value === false) {
    error = 'You must accept these terms';
  }

  if (field === 'attestation_terms' && value === false) {
    error = 'You must accept these terms';
  }

  if (field === 'partner_attestation' && value === false) {
    error = 'You must accept these terms';
  }

  if (error !== undefined) {
    return {valid: false, error};
  }

  return {valid: true};
};

const transformCheckoutFormField = (
  field: keyof CheckoutFormValues,
  value: CheckoutFormValues[keyof CheckoutFormValues],
) => {
  if (field === 'address_zip' && typeof value === 'string') {
    return value.replace(/[^0-9]*/g, '').substr(0, 5);
  }

  return value;
};

export interface CheckoutFormProps {
  initialValues: Partial<CheckoutFormValues>;
}

export const getDefaultValues = (): CheckoutFormValues => ({
  name: '',
  address_country: 'US',
  address_zip: '',
  attestation_legal: false,
  attestation_terms: false,
  partner_attestation: false,
  signature: '',
  auto_renewal: true,

  email: '',
});

export const useCheckoutForm = ({initialValues}: CheckoutFormProps) => {
  const [formState, formActions] = useForm<
    CheckoutFormValues,
    Partial<CheckoutFormValues>
  >({
    initialValues: {...initialValues},
    map: mapCheckoutForm,
    transform: transformCheckoutFormField,
    validate: validateCheckoutFormField,
    defaultValues: getDefaultValues(),
  });
  const isMounted = React.useRef<boolean>(true);

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  return [formState, formActions] as const;
};
