import * as React from 'react';
import {useFela} from 'react-fela';

import {useNotifications} from '../../hooks/useNotifications';

import {NOTIFICATION_AREA, NOTIFICATION} from './styles';

export const NotificationArea = () => {
  const notifications = useNotifications();
  const {css} = useFela();

  return (
    <div className={css(NOTIFICATION_AREA)}>
      {notifications.map((notification) => {
        const e = notification.render();

        return e ? (
          <div className={css(NOTIFICATION)} key={notification.id}>
            {e}
          </div>
        ) : null;
      })}
    </div>
  );
};
