import tabbable from 'tabbable';

export type Reason = 'key' | 'pointer' | 'focus';

export interface SetFocusHandler {
  (elements: HTMLElement[]): void;
}

type MouseDownEvent = MouseEvent & {type: 'mousedown'};
type FocusInEvent = FocusEvent & {type: 'focusin'};
type TouchStartEvent = TouchEvent & {type: 'touchstart'};
type KeyDownEvent = KeyboardEvent & {type: 'keydown'};

type CloseEvent =
  | MouseDownEvent
  | FocusInEvent
  | TouchStartEvent
  | KeyDownEvent;

export interface CloseHandler {
  (event: CloseEvent, reason: Reason): void;
}

export interface FocusScopeOptions {
  /**
   * When set to `true` the focus scope will automatically focus the first
   * tabbable child element when activated.
   *
   * Optionally provide a function which returns an html element to receive
   * focus.
   */
  setFocus?: boolean | ((element: HTMLElement) => HTMLElement | null);

  /**
   * Prevent mouse and keyboard events from propagating outside of the focus
   * scope element.
   */
  cancelEvents?: boolean;

  /**
   * Close callback. Called when the user clicks or focuses outside the modal
   * element, or presses the esc key.
   */
  onClose?: CloseHandler;

  onMouseDown?: (event: MouseDownEvent) => void;

  onTouchStart?: (event: TouchStartEvent) => void;

  /**
   * Prevent focus from leaving the modal element. When set, focus events
   * targeting elements outside the modal element will be redirected within, tab
   * focus navigation will cycle within the modal element, and click event
   * default behavior outside the modal element will be prevented.
   */
  trapFocus?: boolean;
}

// Keep track of multiple mounted focus traps, with topmost active one at the
// head of the list.
const stack: FocusScope[] = [];

function sortStack() {
  // Sort the stack based on document position. The deepest nested scope is the
  // first element of the sorted list, the outermost first scope nearest the
  // top of the document is the last element.

  stack.sort((a, b) => {
    // The compareDocumentPosition method returns a bitmask.
    // `a.compareDocumentPosition(b) & 4` is true if a is a child of b or if a
    // follows b in the DOM
    // see: https://developer.mozilla.org/en-US/docs/Web/API/Node/compareDocumentPosition

    // eslint-disable-next-line no-bitwise
    if (a.element.compareDocumentPosition(b.element) & 4) {
      return 1;
    }

    return -1;
  });
}

function handleFocusInCapture(event: FocusEvent) {
  sortStack();

  for (const instance of stack) {
    instance.handleFocusInCapture(event);
  }
}

function handlePointerCapture(event: MouseEvent | TouchEvent) {
  sortStack();

  for (const instance of stack) {
    const cancelled = instance.handlePointerCapture(event);
    if (cancelled) {
      break;
    }
  }
}

function handleKeyDownCapture(event: KeyboardEvent) {
  sortStack();

  for (const instance of stack) {
    const cancelled = instance.handleKeyDownCapture(event);
    if (cancelled) {
      break;
    }
  }
}

function register(instance: FocusScope) {
  stack.unshift(instance);

  if (stack.length === 1) {
    window.addEventListener('focusin', handleFocusInCapture, true);
    window.addEventListener('mousedown', handlePointerCapture, true);
    window.addEventListener('touchstart', handlePointerCapture, true);
    window.addEventListener('keydown', handleKeyDownCapture, true);
  }
}

function unregister(instance: FocusScope) {
  const index = stack.indexOf(instance);
  if (index !== -1) {
    stack.splice(index, 1);
  }

  if (stack.length === 0) {
    window.removeEventListener('focusin', handleFocusInCapture, true);
    window.removeEventListener('mousedown', handlePointerCapture, true);
    window.removeEventListener('touchstart', handlePointerCapture, true);
    window.removeEventListener('keydown', handleKeyDownCapture, true);
  }
}

export class FocusScope {
  options: FocusScopeOptions;
  element: HTMLElement;
  restoreFocusElement: HTMLElement = document.body;
  lastFocusedElement?: HTMLElement;

  constructor(element: HTMLElement, options: FocusScopeOptions = {}) {
    this.element = element;
    this.options = options;

    register(this);

    // Store a reference to the element focused before the scope is activated,
    // so it focus may be returned to it when the scope is deactivated.
    if (document.activeElement instanceof HTMLElement) {
      this.restoreFocusElement = document.activeElement;
    }

    // Focus the first element within the scope.
    this.setFocus();
  }

  setFocus() {
    if (this.lastFocusedElement) {
      this.lastFocusedElement.focus({preventScroll: true});
      return;
    }

    if (this.options.setFocus === false) {
      return;
    }

    if (typeof this.options.setFocus === 'function') {
      const target = this.options.setFocus(this.element);
      requestAnimationFrame(() => {
        if (target) {
          target.focus({preventScroll: true});
        }
      });
      return;
    }

    const elements = tabbable(this.element);

    if (this.element.contains(document.activeElement)) {
      return;
    }

    requestAnimationFrame(() => {
      if (elements[0]) {
        elements[0].focus({preventScroll: true});
        this.lastFocusedElement = elements[0];
      } else {
        this.element.focus({preventScroll: true});
      }
    });
  }

  remove(restoreFocus: boolean) {
    if (restoreFocus) {
      this.restoreFocusElement.focus({preventScroll: true});
    }

    unregister(this);
  }

  setOptions(options: FocusScopeOptions = {}) {
    if (!this.options.trapFocus && options.trapFocus) {
      this.setFocus();
    }

    this.options = options;
  }

  handleFocusInCapture = (event: FocusEvent) => {
    // Keep last focused element ref updated.
    if (
      event.target instanceof HTMLElement &&
      this.element.contains(event.target)
    ) {
      this.lastFocusedElement = event.target;
      return;
    }

    // In Firefox when you Tab out of an iframe the Document is briefly
    // focused.
    if (event.target instanceof Document) {
      return;
    }

    // The user has tabbed out of the focus scope context. Call the
    // close handler to allow the host component to respond.
    if (!this.options.trapFocus && this.options.onClose) {
      this.options.onClose(event as CloseEvent, 'focus');
      return;
    }

    if (this.options.trapFocus && this === stack[0]) {
      // Focus has left the focus scope context when it should not, pull it back
      // in.
      event.stopImmediatePropagation();

      this.setFocus();
    }
  };

  handlePointerCapture = (event: MouseEvent | TouchEvent): boolean => {
    if (event.defaultPrevented) {
      return false;
    }

    // Ignore then event if the target is within the focus trap.
    if (this.element.contains(event.target as Node)) {
      if (event.type === 'mousedown' && this.options.onMouseDown) {
        this.options.onMouseDown(event as MouseDownEvent);
      } else if (event.type === 'touchstart' && this.options.onTouchStart) {
        this.options.onTouchStart(event as TouchStartEvent);
      }

      return true;
    }

    const shouldCancel =
      !!this.options.trapFocus || !!this.options.cancelEvents;

    // The user has clicked or tapped outside of the focus trap. Call the
    // close handler to allow the host component to respond.
    if (this.options.onClose) {
      this.options.onClose(event as CloseEvent, 'pointer');
    }

    // Prevent click and tap event behavior when focus is trapped. Native
    // select inputs for example prevent the default click behavior when a
    // click closes the input popup.
    if (shouldCancel) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }

    return shouldCancel;
  };

  handleKeyDownCapture = (event: KeyboardEvent): boolean => {
    if (event.defaultPrevented) {
      return false;
    }

    const shouldCancel = !!this.options.cancelEvents;

    // Detect Esc key presses and call the close handler if configured.
    if (this.options.onClose && /^(Esc|Escape)$/.test(event.key)) {
      if (shouldCancel) {
        event.preventDefault();
        event.stopImmediatePropagation();
      }
      this.options.onClose(event as CloseEvent, 'key');
    }

    // Handle cyclic tab navigation within the focus scope context when
    // `trapFocus` is set. Focus will otherwise be allowed to leave the
    // context - which will result in a call to the close handler through the
    // `focusin` event handler above.
    if (this.options.trapFocus && this === stack[0] && event.key === 'Tab') {
      const elements = tabbable(this.element);

      const first = elements[0];
      const last = elements[elements.length - 1];

      // Cycle from the first element to the last element.
      if (event.shiftKey && event.target === first) {
        event.preventDefault();
        event.stopImmediatePropagation();
        last.focus({preventScroll: true});
      }

      // Cycle from the last element to the first element.
      if (!event.shiftKey && event.target === last) {
        event.preventDefault();
        event.stopImmediatePropagation();
        first.focus({preventScroll: true});
      }
    }

    return shouldCancel;
  };
}
