import {StyleFunction} from 'react-fela';

import {
  layoutMaxWidth,
  breakpoints,
  layoutMargin,
  layoutMarginMedium,
} from '@crucible-risk/theme';

export const containerStyle: StyleFunction<{}, {}> = () => ({
  marginRight: 'auto',
  marginLeft: 'auto',

  maxWidth: layoutMaxWidth + layoutMargin * 2,
  paddingLeft: layoutMargin,
  paddingRight: layoutMargin,

  [`@media (min-width: ${breakpoints.medium}px)`]: {
    maxWidth: layoutMaxWidth + layoutMarginMedium * 2,
  },
});

export const containerPaddingStyle: StyleFunction<{}, {}> = () => ({
  paddingLeft: layoutMargin,
  paddingRight: layoutMargin,

  [`@media (min-width: ${breakpoints.medium}px)`]: {
    paddingLeft: layoutMarginMedium,
    paddingRight: layoutMarginMedium,
  },
});
