import {Union, Literal, Static} from 'runtypes';

// see: https://github.com/crucible-risk/servers_common/blob/298c62b/common/models/coverages.py#L8
export const MarketSchema = Union(
  Literal('SURPLUS'),
  Literal('ADMITTED'),
  Literal('CANADA'),
  Literal('UNITED_KINGDOM'),
);

export type Market = Static<typeof MarketSchema>;
