import * as React from 'react';
import {Redirect, Route, RouteProps} from 'react-router-dom';
import {hasSession} from './session';

export interface PageParams {
  program: string;
  partnership: string;
}

export const SecureRoute: React.FC<RouteProps> = ({children, ...rest}) => {
  return (
    <Route
      {...rest}
      render={({location, match}) => {
        const searchParams = new URLSearchParams(location.search);
        const sessionId = searchParams.get('session');
        const hasJwt = !!sessionId && hasSession(sessionId);

        if (sessionId && hasJwt) {
          return children;
        }

        return (
          <Redirect
            to={`/${match.params.partnership}/${match.params.program}/general-info`}
          />
        );
      }}
    />
  );
};
