import React from 'react';

export function updateRef<T>(ref: React.LegacyRef<T> | undefined, value: T) {
  if (typeof ref === 'function') {
    ref(value);
  } else if (ref && typeof ref !== 'string') {
    // eslint-disable-next-line no-param-reassign
    (ref as React.MutableRefObject<T | null>).current = value;
  }
}

export function useCombineRefs<T>(...refs: (React.LegacyRef<T> | undefined)[]) {
  function combinedRef(value: T | null) {
    for (const ref of refs) {
      updateRef(ref, value);
    }
  }

  // Memoize the returned callback ref using the input refs. This prevents
  // unnecessary executions when the input ref values are constant across
  // renders.
  return React.useCallback(combinedRef, refs);
}
