import * as React from 'react';
import {Helmet} from 'react-helmet';
import {useProgram} from '../../components/ContentProvider';
import {QuoteNotSupported} from '../../components/pages/QuoteNotSupported';
import {UseSupportChat} from '/lib/chat';

export const QuoteNotSupportedPage: React.FC = () => {
  const program = useProgram();

  UseSupportChat().show();

  return (
    <>
      <Helmet>
        <title>
          {program.quoteNotSupportedPage.pageTitle ?? program.pageTitle}
        </title>
      </Helmet>
      <QuoteNotSupported content={program.quoteNotSupportedPage} />
    </>
  );
};
