import * as React from 'react';

import type {
  GeneralInfoFormChangeHandler,
  GeneralInfoFormBlurHandler,
  GeneralInfoFormFieldValue,
  GeneralInfoFormValues,
  GeneralInfoFormFlags,
  GeneralInfoValidationErrors,
} from '../../hooks/useGeneralInfoForm';
import type {FieldBlockType} from '../../lib/content';

export type Intent = 'danger' | 'neutral';

export type CompanyDetailsContextType = {
  labelStyle: 'inline' | 'stacked';
  editing: boolean;
  valid: GeneralInfoFormFlags;
  dirty: GeneralInfoFormFlags;
  values: GeneralInfoFormValues;
  handleChange: GeneralInfoFormChangeHandler;
  handleBlur: GeneralInfoFormBlurHandler;
  fieldContent: Record<string, FieldBlockType>;
  hidden: Array<keyof GeneralInfoFormValues>;
  validationErrors?: GeneralInfoValidationErrors;
};

export const CompanyDetailsContext = React.createContext<CompanyDetailsContextType | null>(
  null,
);

export const useCompanyDetailsContext = (
  field: keyof GeneralInfoFormValues,
) => {
  const ctx = React.useContext(CompanyDetailsContext);

  if (!ctx) {
    throw new Error(
      'useCompanyDetailsContext needs to be wrapped in a provider',
    );
  }

  const handleChange = (value: GeneralInfoFormFieldValue) => {
    ctx.handleChange(field, value);
  };

  const handleBlur = () => {
    ctx.handleBlur(field);
  };

  const {label, placeholder} = ctx.fieldContent[field] ?? {};
  const value = ctx.values[field];
  const labelStyle = ctx.labelStyle;
  const editing = ctx.editing;
  const hidden = ctx.hidden.includes(field);
  const intent: Intent =
    ctx.dirty[field] && !ctx.valid[field] ? 'danger' : 'neutral';

  const error =
    ctx.validationErrors !== undefined
      ? ctx.validationErrors[field]
      : undefined;

  return {
    label: label ?? `MISSING LABEL: ${field}`,
    name: field,
    autoComplete: field,
    id: field,
    editing,
    labelStyle,
    placeholder: placeholder ?? '',
    value,
    intent,
    hidden,
    error,
    onChange: handleChange,
    onBlur: handleBlur,
  };
};
