import {IStyle} from 'fela';
import {StyleProps} from 'react-fela';
import {colors} from '@crucible-risk/theme';

import {desktopMediaQuery} from '../../styles';

// Color for this as requested by design
export const customColor = '#B0D8F9';

export const STEPS_CONTAINER: IStyle = {
  display: 'flex',
  width: '100%',
  justifyContent: 'space-around',

  nested: {
    [desktopMediaQuery]: {
      justifyContent: 'normal',
    },
  },
};

export const ITEM_CONTAINER = ({
  index,
  numSteps,
}: StyleProps<
  {},
  {
    index: number;
    numSteps: number;
  }
>): IStyle => {
  const lastStepStyles =
    index && index + 1 === numSteps
      ? {
          flex: 'none',
        }
      : {};

  return {
    position: 'relative',
    display: 'flex',

    nested: {
      [desktopMediaQuery]: {
        flex: '1',
        display: 'inline-block',
        ...lastStepStyles,
      },
    },
  };
};

export const DOT_ICON = ({
  status,
}: StyleProps<{}, {status: string}>): IStyle => {
  const contentColor =
    status === 'active' || status === 'finished' || status === 'half'
      ? colors.blue500
      : customColor;

  return {
    width: '21px',
    height: '21px',
    borderRadius: '100%',
    background: contentColor,
    border: `4px solid ${colors.white}`,

    nested: {
      [desktopMediaQuery]: {
        marginLeft: '62px',
      },
    },
  };
};

export const CONTENT: IStyle = {
  display: 'none',

  nested: {
    [desktopMediaQuery]: {
      display: 'block',
      width: '144px',
      height: 'auto',
      textAlign: 'center',
    },
  },
};

export const TAIL_LINE = ({
  status,
}: StyleProps<{}, {status: string}>): IStyle => {
  const lineColor = status === 'finished' ? colors.blue500 : customColor;

  return {
    display: 'block',

    nested: {
      [desktopMediaQuery]: {
        display: 'block',
        position: 'absolute',
        backgroundColor: lineColor,
        top: 9,
        left: 62,
        width: '100%',
        height: '4px',
        zIndex: -2,
      },
    },
  };
};

export const HALF_TAIL_LINE: IStyle = {
  display: 'block',

  nested: {
    [desktopMediaQuery]: {
      display: 'block',
      position: 'absolute',
      backgroundColor: colors.blue500,
      top: 9,
      left: 62,
      width: '50%',
      height: '4px',
      zIndex: -1,
    },
  },
};

export const TEXT_COLOR = ({
  status,
}: StyleProps<{}, {status: string}>): IStyle => {
  return {
    color: status === 'disabled' || !status ? customColor : undefined,
  };
};
