import React from 'react';
import {useFela} from 'react-fela';

import {colors} from '@crucible-risk/theme';
import {Spacing} from '@crucible-risk/spacing';
import {Spinner} from '@crucible-risk/spinner';
import {Typography} from '@crucible-risk/typography';

const FADE_DURATION_MS = 1000;
const MIN_VISIBLE_DURATION_MS = 500;

declare global {
  interface Window {
    _clearLoading(): void;
  }
}

export const AppLoading = () => {
  const {css} = useFela();

  return (
    <div
      id="loading"
      className={css({
        position: 'absolute',
        top: 0,
        right: 0,
        bottom: 0,
        left: 0,
        overflow: 'hidden',
        zIndex: 99999,
      })}
    >
      <div
        className={css({
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          background: colors.white,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          transformOrigin: '50%',
          transition: `opacity ${FADE_DURATION_MS}ms`,
          opacity: 1,
        })}
      >
        <Spinner size={64} color="blue500" />
        <div className={css({height: 0})}>
          <Spacing height="16" />
          <Typography variant="labelRegular">LOADING</Typography>
        </div>
      </div>
      <script
        dangerouslySetInnerHTML={{
          __html: `
          (function(){
            var loading = document.getElementById('loading');
            var inner = loading.childNodes[0];
            var start = Date.now();
            _clearLoading = function() {
              setTimeout(function() {
                inner.style.opacity = '0';
                inner.style.pointerEvents = 'none';
                setTimeout(function() {
                  var p = loading.parentElement;
                  if (p) {
                    p.removeChild(loading);
                  }
                }, ${FADE_DURATION_MS});
              }, Math.max(0, ${MIN_VISIBLE_DURATION_MS} - (Date.now() - start)));
            };
          })();`,
        }}
      />
    </div>
  );
};
