import {useHistory, useParams} from 'react-router-dom';
import {InsurancePolicy} from '@crucible-risk/sku-api-schema';

import {PageParams} from '/lib/routing';

import {
  useGeneralInfoForm,
  getGeneralInfoValuesFromInsurancePolicy,
  getGeneralInfoValuesFromQueryParams,
} from '/hooks/useGeneralInfoForm';
import {affinityReferrerUUID} from '/hooks/useAffinityReferrer';

export const useGeneralInfoPageState = (
  sessionId: string | undefined,
  insurancePolicy: InsurancePolicy | null,
  agencyProgramFlag: boolean,
  defaultProgram?: string,
  defaultEndDate?: string,
) => {
  const params = useParams<PageParams>();
  const history = useHistory();
  const queryParams = new URLSearchParams(window.location.search);
  const formValues = insurancePolicy
    ? getGeneralInfoValuesFromInsurancePolicy(
        insurancePolicy,
        affinityReferrerUUID ?? '',
      )
    : getGeneralInfoValuesFromQueryParams(
        queryParams,
        affinityReferrerUUID ?? '',
      );
  const [formState, formActions] = useGeneralInfoForm({
    initialValues: {
      ...formValues,
    },
    sessionId: sessionId ?? '',
    editing: false,
    validateOnMount: false,
    agencyProgramFlag,
    defaultProgram,
    defaultEndDate,
  });

  const actions = {
    handleSubmit: () =>
      formActions.save().then((policy) => {
        if (policy) {
          history.push({
            pathname: `/${params.partnership}/${params.program}/select-plan`,
            search: history.location.search,
          });
        }
      }),
  };

  return [
    {
      ...formState,
    },
    {
      ...formActions,
      ...actions,
    },
  ] as const;
};
