import * as React from 'react';
import {Dialog} from '@crucible-risk/dialog';
import {Spacing} from '@crucible-risk/spacing';
import {Typography as T} from '@crucible-risk/typography';
import {CloseIcon} from '@crucible-risk/icon';
import {Button} from '@crucible-risk/button';
import {Flex} from '@crucible-risk/flex';
import {Configuration} from '@crucible-risk/sku-api-schema';

import {formatCurrency} from '../../utils/intl';
import {SelectPlanPageType} from '../../lib/content';
import {Responsive} from '../Responsive';

interface FTFDialogProps {
  content: SelectPlanPageType['modal'];
  ftfConfigurations: {
    withoutFTF: Configuration;
    withFTF: Configuration;
  };
  submittingId?: number;
  submitting?: boolean;
  onSelect: (id: number) => void;
  onClose: () => void;
}

export const FTFDialog = ({
  ftfConfigurations,
  submittingId,
  submitting,
  onSelect,
  content,
  onClose,
}: FTFDialogProps) => {
  const ftfCoverage = ftfConfigurations.withFTF.coverages.find(
    (coverage) => coverage.coverage === 'funds_transfer',
  );

  const handleSelect = (id: number) => () => onSelect(id);

  return (
    <Dialog
      open
      shade
      closeButton={
        <Button
          size="small"
          minimal
          intent="neutral"
          square
          onClick={onClose}
          sharpCorners
        >
          <CloseIcon aria-label="close dialog" />
        </Button>
      }
    >
      <Spacing vertical="48" horizontal="48">
        <Spacing bottom="8">
          <T
            className="h3 fg-title"
            fill
            align="center"
            variant="displayXSmall"
            weight="semibold"
            color="bodyCopy"
          >
            Cyber coverage up to{' '}
            {formatCurrency(ftfConfigurations.withoutFTF.limit.amount / 100, {
              currency: ftfConfigurations.withoutFTF.limit.code,
              compact: false,
            })}
          </T>
        </Spacing>
        <Spacing bottom="40">
          <T
            className="body3 fg-title"
            fill
            align="center"
            variant="bodyRegular"
            weight="semibold"
            color="bodyCopy"
          >
            {formatCurrency(ftfConfigurations.withoutFTF.limit.amount / 100, {
              currency: ftfConfigurations.withoutFTF.limit.code,
              compact: true,
            })}{' '}
            Policy Limit |{' '}
            {formatCurrency(
              ftfConfigurations.withoutFTF.retention.amount / 100,
              {
                currency: ftfConfigurations.withoutFTF.retention.code,
                compact: false,
              },
            )}{' '}
            Policy Deductible
          </T>
        </Spacing>
        <Spacing bottom="8">
          <T
            className="h3 fg-title"
            variant="displayXSmall"
            weight="semibold"
            color="black"
            fill
            align="center"
          >
            {content.heading}
          </T>
        </Spacing>
        <Spacing bottom="40">
          <T
            className="body3 fg-body"
            variant="bodyRegular"
            weight="normal"
            color="headline"
            fill
            align="center"
          >
            {content.body}
            {ftfCoverage && ftfCoverage.sublimit && (
              <>
                <br />
                FTF will be covered up to{' '}
                {formatCurrency(ftfCoverage.sublimit.amount / 100, {
                  currency: ftfCoverage.sublimit.code,
                  compact: true,
                })}
              </>
            )}
            .
          </T>
        </Spacing>
        <Responsive>
          <Responsive.Column>
            <Spacing bottom="8">
              <T
                className="body5 fg-primary"
                variant="bodyXSmall"
                weight="semibold"
                color="blue500"
                fill
                align="center"
                transform="uppercase"
              >
                {content.ftf.heading}
              </T>
            </Spacing>
            <Spacing bottom="8">
              <T
                className="body3 fg-title"
                variant="bodySmall"
                weight="semibold"
                fill
                align="center"
                color="black"
              >
                {content.ftf.prefix}{' '}
                <T
                  className="h3 fg-title"
                  variant="displayXSmall"
                  weight="semibold"
                >
                  {formatCurrency(
                    ftfConfigurations.withFTF.premium.amount / 100,
                    {
                      currency: ftfConfigurations.withFTF.premium.code,
                      compact: false,
                    },
                  )}
                </T>
              </T>
            </Spacing>
            <Flex col align="center" fill>
              <Button
                className="fg-inverted bg-primary"
                size="small"
                onClick={handleSelect(ftfConfigurations.withFTF.id)}
                loading={
                  submitting && submittingId === ftfConfigurations.withFTF.id
                }
                disabled={
                  submitting && submittingId !== ftfConfigurations.withFTF.id
                }
                sharpCorners
              >
                {content.ftf.button}
              </Button>
            </Flex>
          </Responsive.Column>
          <Responsive.Column>
            <Responsive.Mobile>
              <Spacing height="24" />
            </Responsive.Mobile>
            <Spacing bottom="8">
              <T
                className="body5 fg-primary"
                variant="bodyXSmall"
                weight="semibold"
                color="blue500"
                fill
                align="center"
                transform="uppercase"
              >
                {content.current.heading}
              </T>
            </Spacing>
            <Spacing bottom="8">
              <T
                className="body3 fg-title"
                variant="bodySmall"
                weight="semibold"
                fill
                align="center"
                color="black"
              >
                {content.current.prefix}{' '}
                <T
                  className="h3 fg-title"
                  variant="displayXSmall"
                  weight="semibold"
                >
                  {formatCurrency(
                    ftfConfigurations.withoutFTF.premium.amount / 100,
                    {
                      currency: ftfConfigurations.withoutFTF.premium.code,
                      compact: false,
                    },
                  )}
                </T>
              </T>
            </Spacing>
            <Flex col align="center" fill>
              <Button
                className="outline-primary border-primary bg-panel fg-primary"
                outline
                background
                size="small"
                onClick={handleSelect(ftfConfigurations.withoutFTF.id)}
                loading={
                  submitting && submittingId === ftfConfigurations.withoutFTF.id
                }
                disabled={
                  submitting && submittingId !== ftfConfigurations.withoutFTF.id
                }
                sharpCorners
              >
                {content.current.button}
              </Button>
            </Flex>
          </Responsive.Column>
        </Responsive>
      </Spacing>
    </Dialog>
  );
};

FTFDialog.displayName = 'FTFDialog';
