import * as React from 'react';
import {useFela} from 'react-fela';
import {HIGHLIGHT} from './styles';

interface TitleHighlightProps {
  title: string;
}

export const TitleHighlight = ({title}: TitleHighlightProps) => {
  const match = title.match(/(.*)(__.*__)(.*)/);
  const {css} = useFela();

  if (!match) {
    return <>{title}</>;
  }

  return (
    <>
      {match.slice(1).map((section) => {
        if (section.startsWith('__') && section.endsWith('__')) {
          // letters that are descenders - ref: https://en.wikipedia.org/wiki/Descender
          // words with descenders need more padding to cover the tail portion with highlight
          const hasDescenders = new RegExp('[gjqpy]').test(section)
            ? '12px'
            : '8px';

          return (
            <span
              key={section}
              className={css({...HIGHLIGHT, paddingBottom: hasDescenders})}
            >
              {section.substring(2, section.length - 2)}
            </span>
          );
        }
        return section;
      })}
    </>
  );
};
