import React from 'react';
import ReactDom from 'react-dom';

export function createPortal() {
  let currentElement: HTMLDivElement | null = null;
  const listeners: ((element: HTMLDivElement | null) => void)[] = [];

  const Sink: React.FC = ({children}) => {
    const [element, setElement] = React.useState(currentElement);

    React.useEffect(() => {
      setElement(currentElement);

      listeners.push(setElement);

      return () => {
        const index = listeners.indexOf(setElement);
        listeners.splice(index, 1);
      };
    }, [setElement]);

    if (element) {
      return ReactDom.createPortal(children, element);
    }

    return null;
  };

  const Well: React.FC = () => {
    const ref = React.useCallback((element: HTMLDivElement | null) => {
      if (currentElement && element) {
        throw new Error('Cannot create a duplicate portal Well instance.');
      }

      currentElement = element;

      for (const listener of listeners) {
        listener(element);
      }
    }, []);

    return <div ref={ref} />;
  };

  return {Well, Sink};
}
