import React from 'react';
import {useFela} from 'react-fela';
import {
  CardNumberElement,
  CardExpiryElement,
  CardCvcElement,
} from '@stripe/react-stripe-js';

import {TextInput} from '@crucible-risk/text-input';
import {Typography as T} from '@crucible-risk/typography';
import {Select, Option} from '@crucible-risk/select';

import {VisaLogo} from './VisaLogo';
import {MasterCardLogo} from './MasterCardLogo';
import {AmericanExpressLogo} from './AmericanExpressLogo';
import {DiscoverLogo} from './DiscoverLogo';
import {CVCLogo} from './CVCLogo';
import {FormValues} from '../../lib/form';
import {useCheckoutContext} from '../../pages/Checkout/state';
import {Redacted} from '../Redacted';

import {
  CARD_FORM,
  CARD_FORM_ROW,
  CARD_FORM_ELEMENT,
  CARD_FORM_SECTION,
  ELEMENT_WRAPPER,
  LOGO_WRAPPER,
  CVC_LOGO_WRAPPER,
  STRIPE_INPUT_STYLE,
} from './styles';

export type ChangeHandler = (
  field: keyof PaymentCardData,
  value: FormValues | null,
) => void;
export type CountryData = Array<{
  value: string;
  label: string;
}>;

export type LabelData = {
  name?: string;
  region?: string;
};

export type PlaceholderData = {
  number?: string;
  expiry?: string;
  cvc?: string;
  name?: string;
  address_zip?: string;
};

export type PaymentCardData = {
  name: string;
  address_country: string;
  address_zip: string;
};

export interface PaymentCardForm {
  placeholders?: PlaceholderData;
  labels?: LabelData;
  countries: CountryData;
  data: PaymentCardData;
  cardType?: 'mc' | 'amex' | 'visa' | 'discover' | 'unknown';
  error: Record<keyof PaymentCardData, string | undefined>;
}

export interface PaymentCardFormProps extends PaymentCardForm {
  onChange: ChangeHandler;
}

export const PaymentCardForm = (props: PaymentCardFormProps) => {
  const {
    data,
    onChange,
    countries,
    labels = {},
    placeholders = {},
    cardType = 'unknown',
    error,
  } = props;
  const {css} = useFela();
  const {
    state: {stripeError},
  } = useCheckoutContext();

  const cardLogo = {
    mc: <MasterCardLogo height={24} />,
    amex: <AmericanExpressLogo height={24} />,
    visa: <VisaLogo height={24} />,
    discover: <DiscoverLogo height={24} />,
    unknown: (
      <>
        <VisaLogo height={24} />
        <MasterCardLogo height={24} />
        <AmericanExpressLogo height={24} />
        <DiscoverLogo height={24} />
      </>
    ),
  }[cardType];

  return (
    <section className={css(CARD_FORM)}>
      <div className={css(CARD_FORM_SECTION)}>
        <div className={css(CARD_FORM_ROW)}>
          <div className={css(CARD_FORM_ELEMENT)}>
            <Redacted>
              <div className={css(ELEMENT_WRAPPER)}>
                <CardNumberElement options={{style: STRIPE_INPUT_STYLE}} />
                <div className={css(LOGO_WRAPPER)}>{cardLogo}</div>
              </div>
            </Redacted>
          </div>
        </div>

        <div className={css(CARD_FORM_ROW)}>
          <div className={css(CARD_FORM_ELEMENT)}>
            <Redacted>
              <div className={css(ELEMENT_WRAPPER)}>
                <CardExpiryElement options={{style: STRIPE_INPUT_STYLE}} />
              </div>
            </Redacted>
          </div>

          <div className={css(CARD_FORM_ELEMENT)}>
            <Redacted>
              <div className={css(ELEMENT_WRAPPER)}>
                <CardCvcElement options={{style: STRIPE_INPUT_STYLE}} />
                <div className={css(CVC_LOGO_WRAPPER)}>
                  <CVCLogo height={14} />
                </div>
              </div>
            </Redacted>
          </div>
        </div>

        {stripeError && (
          <T variant="bodySmall" color="red500">
            {stripeError}
          </T>
        )}
      </div>

      <div className={css(CARD_FORM_SECTION)}>
        <div className={css(CARD_FORM_ROW)}>
          <div className={css(CARD_FORM_ELEMENT)}>
            <T
              className="body4 fg-title"
              variant="bodySmall"
              weight="semibold"
              color="black"
            >
              {labels.name ?? 'Name on card'}
            </T>
          </div>
        </div>
        <div className={css(CARD_FORM_ROW)}>
          <div className={css(CARD_FORM_ELEMENT)}>
            <Redacted>
              <TextInput
                placeholder={placeholders.name ?? ''}
                size="small"
                value={data.name}
                onChange={(value) => onChange('name', value)}
                intent={error.name === undefined ? 'neutral' : 'danger'}
              />
            </Redacted>
            {error.name !== undefined && (
              <T color="red500" variant="bodySmall">
                {error.name}
              </T>
            )}
          </div>
        </div>
        <div className={css(CARD_FORM_SECTION)}>
          <div className={css(CARD_FORM_ROW)}>
            <div className={css(CARD_FORM_ELEMENT)}>
              <T
                className="body4 fg-title"
                variant="bodySmall"
                weight="semibold"
                color="black"
              >
                {labels.region ?? 'Country or region'}
              </T>
            </div>
          </div>
          <div className={css(CARD_FORM_ROW)}>
            <div className={css(CARD_FORM_ELEMENT)}>
              <Redacted>
                <Select
                  fill
                  size="small"
                  value={data.address_country}
                  onChange={(value) => onChange('address_country', value)}
                  intent="neutral"
                >
                  {countries.map((country) => (
                    <Option
                      key={country.value}
                      label={country.label}
                      value={country.value}
                      showValue
                    />
                  ))}
                </Select>
              </Redacted>
            </div>
          </div>
          <div className={css(CARD_FORM_ROW)}>
            <div className={css(CARD_FORM_ELEMENT)}>
              <Redacted>
                <TextInput
                  placeholder={placeholders.address_zip ?? 'Zip code'}
                  size="small"
                  value={data.address_zip}
                  onChange={(value) => onChange('address_zip', value)}
                  intent={error.name === undefined ? 'neutral' : 'danger'}
                />
              </Redacted>
              {error.address_zip !== undefined && (
                <T color="red500" variant="bodySmall">
                  {error.address_zip}
                </T>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

PaymentCardForm.displayName = 'PaymentCardForm';
