import {RC} from '@crucible-risk/fela-renderer';

import {
  typeVariants,
  formatTypeVariant,
  fontWeights,
  colors,
} from '@crucible-risk/theme';

export const variantStyle: RC<{
  variant?: keyof typeof typeVariants;
}> = ({variant}) => {
  return variant ? formatTypeVariant(typeVariants[variant]) : {};
};

export const displayStyle: RC<{
  flex: boolean;
  fill: boolean;
  ellipsis: boolean;
}> = ({flex, fill, ellipsis}) => {
  return {
    flex: fill || ellipsis ? '1 1 auto' : '0 0 auto',
    display:
      fill || ellipsis
        ? flex
          ? 'flex'
          : 'block'
        : flex
        ? 'inline-flex'
        : 'inline',
  };
};

export const alignStyle: RC<{
  align?: 'left' | 'center' | 'right';
}> = ({align}) => {
  return {
    textAlign: align,
  };
};

export const weightStyle: RC<{
  weight?: keyof typeof fontWeights;
}> = ({weight}) => {
  return {
    fontWeight: weight ? fontWeights[weight] : undefined,
  };
};

export const colorStyle: RC<{
  color: keyof typeof colors;
}> = ({color: colorName}) => {
  return {
    color: colorName ? colors[colorName] : undefined,
  };
};

export const whiteSpaceStyle: RC<{
  ellipsis: boolean;
  nowrap: boolean;
}> = ({ellipsis, nowrap}) => {
  return {
    whiteSpace: ellipsis || nowrap ? 'nowrap' : undefined,
    overflow: ellipsis ? 'hidden' : undefined,
    textOverflow: ellipsis ? 'ellipsis' : undefined,
  };
};

export const transformStyle: RC<{
  transform: 'capitalize' | 'lowercase' | 'uppercase';
}> = ({transform}) => {
  return {
    textTransform: transform,
  };
};

export const underlineStyle: RC<{underline: boolean}> = ({underline}) => {
  return {
    textDecoration: underline ? 'underline' : undefined,
  };
};
