import {Record, Array, String, Number, Null, Static} from 'runtypes';

import {MarketSchema, InsuranceProgramSchema} from '@crucible-risk/api-schema';

import {CurrencySchema} from './currency';
import {CoverageSchema} from './coverage';

export const ConfigurationSchema = Record({
  id: Number,
  base_configuration_id: Number.Or(Null),
  display_name: String.Or(Null),
  description: String.Or(Null),
  retention: CurrencySchema,
  premium: CurrencySchema,
  limit: CurrencySchema,
  insurance_market: MarketSchema,
  insurance_program: InsuranceProgramSchema,
  coverages: Array(CoverageSchema),
});

export type Configuration = Static<typeof ConfigurationSchema>;
