import React from 'react';
import {useFela, CssFunction} from 'react-fela';

import {
  groupStyle,
  groupLabelWrapperStyle,
  groupLabelStyle,
} from './listBox.fela';

export function renderGroupLabel({
  css,
  label,
}: {
  css: CssFunction<{}, {}>;
  label?: React.ReactNode;
  value?: string;
}) {
  return (
    <div className={css(groupLabelWrapperStyle)}>
      <div className={css(groupLabelStyle)}>{label}</div>
    </div>
  );
}

interface Props extends React.HTMLAttributes<HTMLLIElement> {
  label: React.ReactNode;
  value?: string;
}

export const GroupRefComponent = (
  {children, label, value, ...rest}: Props,
  ref: React.Ref<HTMLLIElement>,
) => {
  const {css} = useFela();

  return (
    <li ref={ref} {...rest} className={css(groupStyle)} role="group">
      {renderGroupLabel({css, label})}
      <ul>{children}</ul>
    </li>
  );
};

export const Group = React.forwardRef(GroupRefComponent);
Group.displayName = 'Group';

export type GroupAttributes = JSX.LibraryManagedAttributes<typeof Group, Props>;

export type GroupElement = React.FunctionComponentElement<
  Props & React.RefAttributes<HTMLLIElement>
>;
