import React, {Fragment} from 'react';
import {useFela} from 'react-fela';
import {Spinner} from '@crucible-risk/spinner';

import {ChangeFunction, Question} from './ApplicationQuestions';
import {QuestionInputSet} from './EditView';
import {Radio} from './Radio';
import {Hr} from '../Hr';

import {childQuestions} from './child-questions';

import {INPUT_COLUMN, INPUT_ROW} from './styles';

interface YesNoQuestionProps {
  disabled: boolean;
  currentQuestion: Question;
  onChange: ChangeFunction;
  questionInfo: Record<string, string>;
  companyName: string;
  active: boolean;
}

export const YesNoQuestion: React.FC<YesNoQuestionProps> = ({
  currentQuestion,
  onChange,
  disabled,
  questionInfo,
  companyName,
  active,
}) => {
  const {css} = useFela();

  return (
    <Fragment key={currentQuestion.id}>
      {/* Child Questions are indented and dont need an HR */}
      {!childQuestions[currentQuestion.id] && <Hr />}

      <QuestionInputSet
        companyName={companyName}
        questionInfo={questionInfo}
        question={currentQuestion}
        inputs={
          <div className={css(INPUT_ROW)}>
            <div className={css(INPUT_COLUMN)}>
              <Radio
                disabled={disabled}
                value="No"
                label="No"
                checked={currentQuestion.answer_text === 'No'}
                questionKey={currentQuestion.id}
                onChange={(value: string) => {
                  onChange(currentQuestion, value);
                }}
              />
            </div>

            <div className={css(INPUT_COLUMN)}>
              <Radio
                disabled={disabled}
                value="Yes"
                label="Yes"
                checked={currentQuestion.answer_text === 'Yes'}
                questionKey={currentQuestion.id}
                onChange={(value: string) => {
                  onChange(currentQuestion, value);
                }}
              />
            </div>
            <div
              className={css(INPUT_COLUMN)}
              style={{alignSelf: 'center', minWidth: 16}}
            >
              {active && <Spinner size={0} />}
            </div>
          </div>
        }
      />
    </Fragment>
  );
};

YesNoQuestion.displayName = 'YesNoQuestion';
