import React from 'react';
import {useFela, CssFunction} from 'react-fela';
import {Divider} from '@crucible-risk/divider';

import {separatorStyle, labelWrapperStyle, labelStyle} from './listBox.fela';

export function renderSeparatorLabel({
  css,
  label,
  value = '',
}: {
  css: CssFunction<{}, {}>;
  label?: React.ReactNode;
  value?: string;
}) {
  return (
    <div className={css(labelWrapperStyle)}>
      <div className={css(labelStyle)}>{label}</div>
    </div>
  );
}

interface Props extends React.HTMLAttributes<HTMLLIElement> {}

export const SeparatorRefComponent = (
  rest: Props,
  ref: React.Ref<HTMLLIElement>,
) => {
  const {css} = useFela();

  return (
    <li ref={ref} {...rest} className={css(separatorStyle)} role="separator">
      <Divider />
    </li>
  );
};

export const Separator = React.forwardRef(SeparatorRefComponent);
Separator.displayName = 'Separator';

export type SeparatorAttributes = JSX.LibraryManagedAttributes<
  typeof Separator,
  Props
>;

export type SeparatorElement = React.FunctionComponentElement<
  Props & React.RefAttributes<HTMLLIElement>
>;
