import React from 'react';
import {useFela} from 'react-fela';
import {useSpring, animated, useTransition, config} from '@react-spring/web';

import {Spinner} from '@crucible-risk/spinner';
import {useA11yKeyEvents} from '@crucible-risk/a11y-key-events-hook';
import {combineHandlers} from '@crucible-risk/combine-handlers';

import {sizes, intents} from './button.config';

import {
  buttonStyle,
  colorStyle,
  spinnerStyle,
  labelStyle,
  statusStyle,
  appendStyle,
  appendStartStyle,
  appendEndStyle,
  linkButtonStyle,
} from './button.fela';

const AnimatedSpan = animated.span as any;

export interface BaseProps<TElement extends HTMLElement>
  extends React.HTMLAttributes<TElement> {
  /**
   * Button text label. Can be any single React element.
   */
  label?: React.ReactNode;

  /**
   * Render an element aligned to the left of the button label.
   */
  appendStart?: React.ReactNode;

  /**
   * Render an element aligned to the right of the button label.
   */
  appendEnd?: React.ReactNode;

  /**
   * Renders the button with all sides padded equally.
   */
  tight?: boolean;

  /**
   * If set to true, the button will display a centered loading spinner instead
   * of its contents. The width of the button is not affected by the value of
   * this prop.
   */
  loading?: boolean;

  /**
   * Button size.
   *
   * @default "regular"
   */
  size?: keyof typeof sizes;

  /**
   * Render the button with a white background and solid color border.
   */
  outline?: boolean;

  background?: boolean;

  /**
   * Render the button with a transparent background which is only visible on hover.
   */
  minimal?: boolean;

  /**
   * Visual intent color to apply to the button.
   *
   * @default "primary"
   */
  intent?: keyof typeof intents;

  /**
   * Whether this button should expand to fill its container.
   */
  fill?: boolean;

  /**
   * Whether button should have equal sides.
   */
  square?: boolean;

  /**
   * Whether button should have 90 degree corners, as opposed to the default rounded ones. This is the current Active
   * style standards, but not all sites in this repo are up those standards, so this is a non-default option. The
   * default value for this bool can be changed to true when all modules use sharp corners.
   */
  sharpCorners?: boolean;

  /**
   * Disabled specifies whether a button or anchor should be usable.
   */
  disabled?: boolean;

  children?: React.ReactNode;
}

function renderButton<
  T extends 'button' | 'a',
  P extends BaseProps<any> & {children?: React.ReactNode}
>(type: T, props: P) {
  const {
    children,
    label = children,
    appendStart,
    appendEnd,
    size = 'regular',
    intent = 'primary',
    tight,
    outline,
    background,
    minimal,
    fill = false,
    loading = false,
    square,
    sharpCorners = false,
    disabled,
    className,
    'aria-disabled': ariaDisabled = disabled,
    ...rest
  } = props;

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const {css} = useFela({
    fill,
    size,
    outline,
    background,
    minimal,
    intent,
    loading,
    tight,
    square,
    sharpCorners,
  });

  // There don't seem to be any official best practices here.
  // see: https://github.com/Shopify/polaris-react/issues/1212
  const ariaProps: React.HTMLAttributes<T> = loading
    ? {role: 'alert', 'aria-busy': true}
    : {};

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const transition = useTransition(loading, {
    from: {opacity: 0, transform: 'scale(3)'},
    enter: {opacity: 1, transform: 'scale(1)'},
    leave: {opacity: 0, transform: 'scale(4)'},
    config: config.gentle,
  });

  const cn = [className, css(buttonStyle, colorStyle)]
    .filter(Boolean)
    .join(' ');

  return React.createElement(
    type,
    {
      ...rest,
      className: cn,
      disabled,
      'aria-disabled': ariaDisabled,
      ...ariaProps,
    },
    !!appendStart && (
      <span className={css(appendStyle, appendStartStyle)}>{appendStart}</span>
    ),
    <AnimatedSpan
      // eslint-disable-next-line react-hooks/rules-of-hooks
      style={useSpring({
        opacity: loading ? 0 : 1,
        transform: loading ? 'scale(0.9)' : 'scale(1)',
        config: config.gentle,
      })}
      className={css(labelStyle)}
    >
      {label}
    </AnimatedSpan>,
    !!appendEnd && (
      <span className={css(appendStyle, appendEndStyle)}>{appendEnd}</span>
    ),
    transition(
      (style, item) =>
        item && (
          <AnimatedSpan style={style} className={css(spinnerStyle, {})}>
            <Spinner size={sizes[size]?.height - 16} />
            <span className={css(statusStyle, {})}>Loading</span>
          </AnimatedSpan>
        ),
    ),
  );
}

export interface ButtonProps
  extends BaseProps<HTMLButtonElement>,
    React.ButtonHTMLAttributes<HTMLButtonElement> {}

export const ButtonRefComponent = (
  props: ButtonProps,
  ref: React.Ref<HTMLButtonElement>,
) => {
  return renderButton('button', {
    type: 'button',
    ref,
    ...props,
  });
};

export const Button = React.forwardRef(ButtonRefComponent);
Button.displayName = 'Button';

export type ButtonAttributes = JSX.LibraryManagedAttributes<
  typeof Button,
  ButtonProps
>;

export interface AnchorButtonProps
  extends BaseProps<HTMLAnchorElement>,
    React.AnchorHTMLAttributes<HTMLAnchorElement> {}

export const AnchorButtonRefComponent = (
  props: AnchorButtonProps,
  ref: React.Ref<HTMLAnchorElement>,
) => {
  const {disabled, href, onKeyDown, onKeyUp, ...rest} = props;

  const [onKeyDownA11y, onKeyUpA11y] = useA11yKeyEvents();

  const linkProps = {
    href: disabled ? undefined : href,
    onKeyDown: combineHandlers(onKeyDown, onKeyDownA11y),
    onKeyUp: combineHandlers(onKeyUp, onKeyUpA11y),
  };

  return renderButton('a', {
    ref,
    ...rest,
    ...linkProps,
  });
};

export const AnchorButton = React.forwardRef(AnchorButtonRefComponent);

export type AnchorButtonAttributes = JSX.LibraryManagedAttributes<
  typeof AnchorButton,
  AnchorButtonProps
>;

function renderLinkButton<
  T extends 'button' | 'a',
  P extends BaseProps<any> & {children?: React.ReactNode}
>(type: T, {size, intent, className, ...rest}: P) {
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const {css} = useFela({
    size,
    intent,
  });

  const cn = [className, css(linkButtonStyle)].filter(Boolean).join(' ');

  return React.createElement(type, {
    ...rest,
    className: cn,
  });
}

export const LinkButtonRefComponent = (
  {type = 'button', ...rest}: ButtonProps,
  ref: React.Ref<HTMLButtonElement>,
) => {
  return renderLinkButton('button', {
    ref,
    type,
    ...rest,
  });
};

export const LinkButton = React.forwardRef(LinkButtonRefComponent);

export type LinkButtonAttributes = JSX.LibraryManagedAttributes<
  typeof LinkButton,
  ButtonProps
>;

export const LinkAnchorButtonRefComponent = (
  {disabled, href, onKeyDown, onKeyUp, ...rest}: AnchorButtonProps,
  ref: React.Ref<HTMLAnchorElement>,
) => {
  const [onKeyDownA11y, onKeyUpA11y] = useA11yKeyEvents();

  const linkProps = {
    href: disabled ? undefined : href,
    onKeyDown: combineHandlers(onKeyDown, onKeyDownA11y),
    onKeyUp: combineHandlers(onKeyUp, onKeyUpA11y),
  };

  return renderLinkButton('a', {
    ref,
    ...rest,
    ...linkProps,
  });
};

export const LinkAnchorButton = React.forwardRef(LinkAnchorButtonRefComponent);

export type LinkAnchorButtonAttributes = JSX.LibraryManagedAttributes<
  typeof LinkAnchorButton,
  ButtonProps
>;
