import React from 'react';

interface KeyDownEventHandler<T = Element> {
  (event: React.KeyboardEvent<T>): void;
}

interface KeyUpEventHandler<T = Element> {
  (event: React.KeyboardEvent<T>): void;
}

export function useA11yKeyEvents<TElement extends HTMLElement = HTMLElement>(
  setActive?: (active: boolean) => void,
) {
  const activeTargetRef = React.useRef<TElement | null>(null);

  const updateActiveTarget = (target: TElement | null) => {
    if (target === activeTargetRef.current) {
      return;
    }

    activeTargetRef.current = target;

    if (setActive) {
      setActive(target !== null);
    }
  };

  const handleKeyDown: KeyDownEventHandler<TElement> = (event) => {
    if (event.defaultPrevented) {
      return;
    }

    if (event.currentTarget instanceof HTMLButtonElement) {
      return;
    }

    if (event.key === ' ') {
      updateActiveTarget(event.currentTarget);

      event.preventDefault();
      event.stopPropagation();
      return;
    }

    if (event.key === 'Enter') {
      event.currentTarget.click();

      event.preventDefault();
      event.stopPropagation();
    }
  };

  const handleKeyUp: KeyUpEventHandler<TElement> = (event) => {
    if (event.defaultPrevented) {
      return;
    }

    updateActiveTarget(null);

    if (event.currentTarget instanceof HTMLButtonElement) {
      return;
    }

    if (event.key === ' ') {
      event.preventDefault();
      event.stopPropagation();

      event.currentTarget.click();
    }
  };

  return [handleKeyDown, handleKeyUp] as const;
}
