import {transparentize} from 'polished';
import {interactiveBorderRadius, colors} from '@crucible-risk/theme';
import {RC} from '@crucible-risk/fela-renderer';

type Region = 'top' | 'right' | 'bottom' | 'left';

export const containerStyle: RC = () => ({
  display: 'flex',
  flexDirection: 'column',
  position: 'absolute',
});

export const backgroundStyle: RC<{}> = () => ({
  position: 'absolute',

  top: 0,
  right: 0,
  bottom: 0,
  left: 0,

  background: colors.white,

  borderRadius: interactiveBorderRadius,

  boxShadow: `0 4px 5px ${transparentize(0.5, colors.coolGray700)}`,
});

export const contentStyle: RC<{
  padded: boolean;
  region: Region;
}> = ({padded = false, region}) => ({
  display: 'flex',
  flexDirection: 'column',

  position: 'relative',
  overflow: 'hidden',
  padding: padded ? 24 : 0,

  background: colors.white,

  borderTopLeftRadius: region === 'top' ? interactiveBorderRadius : undefined,
  borderTopRightRadius: region === 'top' ? interactiveBorderRadius : undefined,
  borderBottomLeftRadius:
    region === 'bottom' ? interactiveBorderRadius : undefined,
  borderBottomRightRadius:
    region === 'bottom' ? interactiveBorderRadius : undefined,
});

export const borderStyle: RC<{}> = () => ({
  pointerEvents: 'none',

  position: 'absolute',

  top: 0,
  right: 0,
  bottom: 0,
  left: 0,

  borderWidth: 1,
  borderStyle: 'solid',
  borderColor: colors.coolGray700,

  borderRadius: interactiveBorderRadius,

  boxShadow: `0 4px 5px ${transparentize(0.5, colors.coolGray700)}`,
});
