import * as React from 'react';
import {ScreenFrame} from '../ScreenFrame';
import {Header, HeaderCoalitionOnly} from '../Header';
import {Footer} from '../Footer';

interface PageProps {
  children: React.ReactNode;
  mainLogoURL: string | null;
  secondaryLogoURL: string | null;
  coalitionBrandOnly?: boolean | null;
}

export const Page = ({
  children,
  mainLogoURL,
  secondaryLogoURL,
  coalitionBrandOnly,
}: PageProps) => {
  let HeaderType;
  if (coalitionBrandOnly === true) {
    HeaderType = HeaderCoalitionOnly;
  } else {
    HeaderType = Header;
  }
  return (
    <ScreenFrame>
      <HeaderType
        mainLogoURL={mainLogoURL}
        secondaryLogoURL={secondaryLogoURL}
      />
      <ScreenFrame.FullSection>{children}</ScreenFrame.FullSection>
      <Footer />
    </ScreenFrame>
  );
};
