import {StyleFunction} from 'react-fela';
import {transparentize} from 'polished';

import {formatTypeVariant, colors} from '@crucible-risk/theme';

import {typeVariant, itemGap, padding} from './listBox.config';

export const listBoxStyle: StyleFunction<{}, {}> = () => ({
  flex: '0 1 auto',

  display: 'block',

  overflowY: 'auto',
});

export const optionStyle: StyleFunction<{}, {}> = () => {
  const hoverColor = transparentize(0.9, colors.bodyCopy);
  const activeColor = transparentize(0.85, colors.bodyCopy);
  const selectedColor = transparentize(0.8, colors.bodyCopy);

  return {
    display: 'block',

    paddingLeft: padding,
    paddingRight: padding,

    paddingTop: itemGap / 2,
    paddingBottom: itemGap / 2,

    cursor: 'pointer',

    '[aria-disabled]': {
      opacity: 0.5,
      cursor: 'default',
    },

    ...formatTypeVariant(typeVariant),

    ':not([aria-disabled])': {
      ':hover': {
        backgroundColor: hoverColor,
      },

      ':active': {
        backgroundColor: activeColor,
      },

      '[aria-selected=true]': {
        backgroundColor: selectedColor,
      },
    },
  };
};

export const groupStyle: StyleFunction<{}, {}> = () => {
  return {
    display: 'block',

    paddingLeft: padding,
    paddingRight: padding,

    ...formatTypeVariant(typeVariant),
  };
};

export const groupChildrenStyle: StyleFunction<{}, {}> = () => {
  return {
    marginLeft: padding,
  };
};

export const separatorStyle: StyleFunction<{}, {}> = () => {
  return {
    display: 'block',

    paddingTop: itemGap / 2,
    paddingBottom: itemGap / 2,
  };
};

export const labelWrapperStyle: StyleFunction<{}, {}> = () => ({
  minHeight: typeVariant.height,

  flex: '1 1 auto',
  display: 'flex',
  minWidth: 0,
});

export const groupLabelWrapperStyle: StyleFunction<{}, {}> = () => ({
  minHeight: typeVariant.height,
  flex: '1 1 auto',
  display: 'flex',
  minWidth: 0,
  position: 'sticky',
  top: 0,
  background: 'rgba(255,255,255,0.5)',
  backdropFilter: 'blur(10px)',
  paddingTop: 6,
  paddingBottom: 6,
});

export const labelStyle: StyleFunction<{}, {}> = () => ({
  flex: '1 1 auto',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
});

export const groupLabelStyle: StyleFunction<{}, {}> = () => ({
  flex: '1 1 auto',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
  fontWeight: 'bold',
});

export const valueStyle: StyleFunction<{}, {}> = () => ({
  flex: '1 0 auto',
  whiteSpace: 'nowrap',

  marginLeft: 8,
  opacity: 0.5,
  fontStyle: 'italic',
  textAlign: 'right',
});
