import * as React from 'react';
import {createParser} from 'gen-unit';

import {TextInput, intents} from '@crucible-risk/text-input';

import {formatCurrency} from '../../utils/intl';

const parser = createParser();

type ChangeHandler = (value: number) => void;

interface MonetaryInputProps {
  name: string;
  value: number | null;
  onChange: ChangeHandler;
  onFocus?: () => void;
  onBlur?: () => void;
  autoFocus?: boolean;
  intent?: keyof typeof intents;
  disabled?: boolean;
  placeholder: string;
}

export const removeCommas = (str: string) => str.replace(/[^0-9.TGMk]/g, '');

const handleChange = (
  value: string,
  onChange: ChangeHandler,
  setDisplayValue: (value: string) => void,
) => {
  /**
   * Input value with commas and non parsable values removed
   */
  const newValue = removeCommas(value);
  const parsedValue = parser(newValue);

  /**
   * Set the value displayed to the user as blank (don't keep the $ around for no reason)
   * or a currency value
   */
  if (newValue === '') {
    setDisplayValue('');
  } else {
    setDisplayValue(
      formatCurrency(parsedValue, {
        fractionDigits: 0,
        currency: 'USD',
      }),
    );
  }

  /**
   * Call the onChange prop with the new value as an int
   */
  onChange(parsedValue);
};

export const MonetaryInput = ({
  name,
  value,
  onChange,
  onFocus,
  onBlur,
  autoFocus,
  intent,
  disabled,
  placeholder,
}: MonetaryInputProps) => {
  const inputEl = React.useRef<HTMLInputElement>(null);

  const [displayValue, setDisplayValue] = React.useState(
    value
      ? formatCurrency(value, {
          fractionDigits: 0,
          currency: 'USD',
        })
      : undefined,
  );

  const [focused, setFocused] = React.useState(false);
  const handleFocus = () => {
    setFocused(true);
    if (onFocus) {
      onFocus();
    }
  };

  React.useEffect(() => {
    if (autoFocus) {
      if (inputEl.current) {
        inputEl.current.focus();
      }
    }
  }, [autoFocus]);
  React.useEffect(() => {
    if (focused && inputEl.current) {
      inputEl.current.select();
    }
  }, [focused]);

  return (
    <TextInput
      id={name}
      placeholder={placeholder}
      size="small"
      intent={intent}
      type="text"
      disabled={disabled}
      autoComplete={name}
      value={displayValue || ''}
      onChange={(newValue) =>
        handleChange(newValue, onChange, (v) => setDisplayValue(v))
      }
      onFocus={handleFocus}
      onBlur={onBlur}
      ref={inputEl}
    />
  );
};
