import * as React from 'react';
import {useLaunchDarkly} from '/component/util/LaunchDarklyProvider/LaunchDarklyContext';

type LDChanges = Record<string, {current: unknown}>;

export const useFlag = <T extends boolean | string | number | undefined>(
  flag: string,
  defaultValue: T,
): {data: T; loading: boolean; error: Error | null} => {
  const client = useLaunchDarkly();
  const [value, setValue] = React.useState<T>(defaultValue);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<Error | null>(null);
  const isMounted = React.useRef<boolean>(true);

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  React.useEffect(() => {
    if (client === null) {
      setLoading(false);
      setValue(defaultValue);
      return;
    }

    const onChange = (changes: LDChanges) => {
      if (!isMounted.current) {
        return;
      }

      if (flag in changes && changes[flag] !== undefined) {
        setValue(changes[flag].current as T);
        setLoading(false);
      }
    };

    const onReady = () => {
      if (!isMounted.current) {
        return;
      }

      const flagValue = client.variation(flag, defaultValue) as T;
      setValue(flagValue);
      setLoading(false);
      setError(null);
    };

    void client
      .waitUntilReady()
      .then(() => {
        if (isMounted.current) {
          onReady();
        }
      })
      .catch((err: Error) => {
        if (isMounted.current) {
          setError(err);
          setLoading(false);
        }
      });

    client.on('ready', onReady);
    client.on('change', onChange);

    return () => {
      client.off('ready', onReady);
      client.off('change', onChange);
    };
  }, [flag, client, defaultValue]);

  return {
    data: value,
    loading,
    error,
  };
};
