import React from 'react';
import {Logo} from './Logo';
import {Wordmark} from './Wordmark';

interface Props {
  size?: number;
}

export const CombinedLogo = (props: Props) => {
  const {size = Logo.height} = props;

  return (
    <div style={{display: 'inline-flex'}}>
      <Logo
        aria-hidden
        size={size}
        style={{marginRight: (size / Logo.height) * 8}}
      />
      <Wordmark size={size} />
    </div>
  );
};
