import React from 'react';
import {useFela} from 'react-fela';

import {Spacing} from '@crucible-risk/spacing';
import {Typography} from '@crucible-risk/typography';
import {CombinedLogo} from '@crucible-risk/logo';
import {Container} from '@crucible-risk/container';

import {JUSTIFY_END, FLEX_CENTER, LOGO_PADDING, ROW} from './styles';
import {Responsive} from '../Responsive';

interface Props {
  /**
   * Leftmost logo (likely AON)
   */
  mainLogoURL: string | null;

  /**
   * Second logo on left
   */
  secondaryLogoURL: string | null;
}

export const Header = ({mainLogoURL, secondaryLogoURL}: Props) => {
  const {css} = useFela();

  return (
    <>
      <Spacing vertical="8">
        <Container>
          <div className={css(ROW)}>
            {!!mainLogoURL && (
              <div className={css(LOGO_PADDING, FLEX_CENTER)}>
                <img src={mainLogoURL} alt="Partner" />
              </div>
            )}

            {!!secondaryLogoURL && (
              <div className={css(LOGO_PADDING, FLEX_CENTER)}>
                <img src={secondaryLogoURL} alt="Program" />
              </div>
            )}

            <div className={css(JUSTIFY_END, FLEX_CENTER)}>
              <div className={css(ROW, FLEX_CENTER)}>
                <Responsive.Desktop>
                  <Typography color="coolGray400" variant="bodySmall">
                    Cyber Insurance provided by
                  </Typography>
                </Responsive.Desktop>
                <Spacing right="8" />
                <CombinedLogo />
              </div>
            </div>
          </div>
        </Container>
      </Spacing>
    </>
  );
};

export const HeaderCoalitionOnly = ({mainLogoURL, secondaryLogoURL}: Props) => {
  const {css} = useFela();

  return (
    <>
      <Spacing vertical="8">
        <Container>
          <div className={css(ROW)}>
            {!!mainLogoURL && (
              <div className={css(LOGO_PADDING, FLEX_CENTER)}>
                <img src={mainLogoURL} alt="Partner" />
              </div>
            )}

            {!!secondaryLogoURL && (
              <div className={css(LOGO_PADDING, FLEX_CENTER)}>
                <img src={secondaryLogoURL} alt="Program" />
              </div>
            )}
          </div>
        </Container>
      </Spacing>
    </>
  );
};
